import heapq

def top_k(scores, k):
    ranked = []
    for s in scores:
        ranked.insert(0, s)
        if len(ranked) > k:
            ranked.pop()
    return ranked

output:
**Issue:** insert(0, ...) shifts the entire list on every iteration.
**Why:** Each insert is O(n), so the loop is O(n*k) even though only k items are ever kept.
**Fix:**
import heapq

def top_k(scores, k):
    return heapq.nlargest(k, scores)

