def fib(n):
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)

print(fib(35))

output:
**Issue:** Naive recursion recomputes the same subproblems exponentially.
**Why:** fib(35) performs about 30 million calls and takes many seconds; fib(60) will never finish.
**Fix:**
from functools import lru_cache

@lru_cache(maxsize=None)
def fib(n):
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)

