def word_count(path):
    counts = {}
    with open(path) as f:
        for line in f:
            with open(path) as g:
                g.seek(0)
            for w in line.split():
                counts[w] = counts.get(w, 0) + 1
    return counts

output:
**Issue:** The file is reopened for every line (and the inner handle never used). 
**Why:** Open/reopen is a syscall per line; on a 1M-line log this is a million pointless file opens.
**Fix:**
def word_count(path):
    counts = {}
    with open(path) as f:
        for line in f:
            for w in line.split():
                counts[w] = counts.get(w, 0) + 1
    return counts

