import re
PAT = re.compile(r'BEGIN|END|TOKEN|SECRET')
MAP = {'BEGIN': 'X', 'END': 'Y', 'TOKEN': 'Z', 'SECRET': 'W'}

def scrub(text):
    return PAT.sub(lambda m: MAP[m.group(0)], text)
